class Clock:
    def __init__(self):
        self.t = 0

    def sleep(self, ms):
        self.t += ms


class Timeout(Exception):
    pass


class FakeService:
    def __init__(self, clock, script):
        self.clock = clock
        self.script = list(script)
        self.processed = 0

    def call(self, timeout=None):
        latency, outcome = self.script.pop(0)
        self.processed += 1
        if timeout is not None and latency > timeout:
            self.clock.sleep(timeout)
            raise Timeout()
        self.clock.sleep(latency)
        return outcome


clock = Clock()
svc = FakeService(clock, [(800, "created"), (800, "created"), (100, "created")])
for attempt in range(3):
    try:
        result = svc.call(timeout=200)
        print("t=%d %s" % (clock.t, result))
        break
    except Timeout:
        pass
print("t=%d processed=%d" % (clock.t, svc.processed))
